import React, { useState } from 'react';
import './styles.css';

export default function App() {
  const [input, setInput] = useState('');
  const [items, setItems] = useState([]);
  const [error, setError] = useState(false);
  const [nextId, setNextId] = useState(1);
  const [filter, setFilter] = useState('all');

  function handleAdd() {
    const name = input.trim();
    if (name === '') {
      setError(true);
      return;
    }
    setItems([...items, { id: nextId, name, quantity: 1, purchased: false }]);
    setNextId(nextId + 1);
    setInput('');
    setError(false);
  }

  function changeQuantity(id, delta) {
    setItems(
      items.map((item) =>
        item.id === id
          ? { ...item, quantity: Math.max(1, item.quantity + delta) }
          : item
      )
    );
  }

  function togglePurchased(id) {
    setItems(
      items.map((item) =>
        item.id === id ? { ...item, purchased: !item.purchased } : item
      )
    );
  }

  function deleteItem(id) {
    setItems(items.filter((item) => item.id !== id));
  }

  const visibleItems = items.filter((item) => {
    if (filter === 'pending') return !item.purchased;
    if (filter === 'purchased') return item.purchased;
    return true;
  });

  const kinds = items.length;
  const pendingUnits = items
    .filter((item) => !item.purchased)
    .reduce((sum, item) => sum + item.quantity, 0);

  return (
    <main className="app">
      <h1>购物清单</h1>
      <div className="add-bar">
        <input
          data-testid="item-input"
          type="text"
          placeholder="商品名称"
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />
        <button data-testid="add-button" type="button" onClick={handleAdd}>
          添加
        </button>
      </div>
      {error && (
        <p data-testid="error-message" className="error">
          请输入商品名称
        </p>
      )}
      <div className="filter-bar">
        <button
          data-testid="filter-all"
          type="button"
          className={filter === 'all' ? 'filter active' : 'filter'}
          onClick={() => setFilter('all')}
        >
          全部
        </button>
        <button
          data-testid="filter-pending"
          type="button"
          className={filter === 'pending' ? 'filter active' : 'filter'}
          onClick={() => setFilter('pending')}
        >
          待购买
        </button>
        <button
          data-testid="filter-purchased"
          type="button"
          className={filter === 'purchased' ? 'filter active' : 'filter'}
          onClick={() => setFilter('purchased')}
        >
          已购买
        </button>
      </div>
      <div className="stats">
        <span className="stat">
          商品种类数：<span data-testid="stat-kinds">{kinds}</span>
        </span>
        <span className="stat">
          待购买总件数：<span data-testid="stat-pending">{pendingUnits}</span>
        </span>
      </div>
      <ul data-testid="item-list" className="item-list">
        {visibleItems.map((item) => (
          <li key={item.id} data-testid="item-row" className="item-row">
            <span className="item-name">{item.name}</span>
            <div className="quantity-controls">
              <button
                data-testid="decrease-button"
                type="button"
                onClick={() => changeQuantity(item.id, -1)}
              >
                减少
              </button>
              <span data-testid="item-quantity" className="item-quantity">
                {item.quantity}
              </span>
              <button
                data-testid="increase-button"
                type="button"
                onClick={() => changeQuantity(item.id, 1)}
              >
                增加
              </button>
            </div>
            <button
              data-testid="toggle-button"
              type="button"
              className={item.purchased ? 'toggle purchased' : 'toggle'}
              onClick={() => togglePurchased(item.id)}
            >
              {item.purchased ? '已购买' : '待购买'}
            </button>
            <button
              data-testid="delete-button"
              type="button"
              className="delete"
              onClick={() => deleteItem(item.id)}
            >
              删除
            </button>
          </li>
        ))}
      </ul>
    </main>
  );
}

